/// <reference types="node" />
import type { StrictUint8Array, SingleInput } from './types'

export interface Ed25519KeyPair {
  publicKey: Buffer
  privateKey: Buffer
  keyType: 'ed25519'
}

export interface X25519KeyPair {
  publicKey: Buffer
  privateKey: Buffer
  curve: 'x25519'
}

export interface SodiumKeys {
  box: {
    publicKey: Buffer
    privateKey: Buffer
    keyType: 'x25519'
  }
  sign: Ed25519KeyPair
  secret: Buffer
  derived: Buffer
}

export function convertPublicKeyToX25519(publicKey: SingleInput): Promise<StrictUint8Array>

export function convertPrivateKeyToX25519(privateKey: SingleInput): Promise<StrictUint8Array>

export function genSignKeyPair(seed: SingleInput): Promise<Ed25519KeyPair>

export function genBoxKeyPair(seed: SingleInput): Promise<X25519KeyPair>

export function getSodiumKeysFromSeed(seed: SingleInput): Promise<SodiumKeys>

export interface SignDetachedOptions {
  message: SingleInput
  privateKey: StrictUint8Array
}

export function signDetached(options: SignDetachedOptions): Promise<Buffer>

export interface VerifyDetachedOptions {
  message: SingleInput
  sig: StrictUint8Array
  publicKey: StrictUint8Array
}

export function verifyDetached(options: VerifyDetachedOptions): Promise<boolean>

export interface SignOptions {
  message: SingleInput
  privateKey: StrictUint8Array
}

export function sign(options: SignOptions): Promise<Buffer>

export interface SignOpenOptions {
  signed: StrictUint8Array
  publicKey: StrictUint8Array
}

export function signOpen(options: SignOpenOptions): Promise<Buffer>

export function encryptAEAD(
  message: SingleInput,
  secretKey: StrictUint8Array,
  nonce: SingleInput,
  associatedData?: SingleInput
): Promise<Buffer>

export function decryptAEAD(
  ciphertext: SingleInput,
  secretKey: StrictUint8Array,
  nonce: SingleInput,
  associatedData?: SingleInput
): Promise<Buffer>

export function encryptSecret(message: SingleInput, secretKey: SingleInput): Promise<Buffer>

export function decryptSecret(
  ciphertextWithNonce: SingleInput,
  secretKey: SingleInput
): Promise<Buffer>

export function encryptBox(
  message: SingleInput,
  toPublic: SingleInput,
  fromPrivate: SingleInput
): Promise<Buffer>

export function decryptBox(
  input: StrictUint8Array,
  fromPublic: SingleInput,
  toPrivate: SingleInput
): Promise<Buffer>

export function encryptSealedBox(message: SingleInput, toPublic: SingleInput): Promise<Buffer>

export function decryptSealedBox(
  input: StrictUint8Array,
  toPublic: SingleInput,
  toPrivate: SingleInput
): Promise<Buffer>
